T["Noch keine Mitspieler von ausserhalb der Gilde.\nWer mit dir in einer Gruppe war, landet automatisch hier."] = "Aún no hay compañeros de fuera de la hermandad.\nQuien haya estado en grupo contigo aparecerá aquí automáticamente."
T["Noch keine Nachrichten. Alles, was ab jetzt im Gildenchat geschrieben wird, landet hier."] = "Aún no hay mensajes. Todo lo que se escriba a partir de ahora en el chat de hermandad aparecerá aquí."
T["Noch keine Positionen."] = "Aún no hay posiciones."
T["Noch keine Posts. Klick auf 'Neuer Schnappschuss' oder auf die Kamera in der Oasis-Leiste!"] = "Aún no hay publicaciones. ¡Haz clic en 'Nueva instantánea' o en la cámara de la barra de Oasis!"
T["Noch keine Punkte.\nSobald ein Offizier einen Raid startet, gibt es Einsatz-Punkte fuer alle, die dabei sind."] = "Aún no hay puntos.\nEn cuanto un oficial inicie una banda, todos los presentes ganarán puntos de esfuerzo."
T["Noch keine Rezepte bekannt.\nOeffne deine Berufsfenster einmal - Oasis teilt sie dann automatisch mit der Gilde."] = "Aún no se conoce ninguna receta.\nAbre tu ventana de profesión una vez – Oasis las compartirá automáticamente con la hermandad."
T["Noch keine Rezepte geteilt.\n\nSobald jemand mit Oasis sein Berufsfenster oeffnet, erscheinen die Rezepte hier. Wer welchen Beruf hat, siehst du schon jetzt:"] = "Aún no hay recetas compartidas.\n\nEn cuanto alguien con Oasis abra su ventana de profesión, aparecerán aquí. Quién tiene cada profesión ya lo puedes ver:"
T["Noch keine Spiele."] = "Aún no hay partidas."
T["Noch keine Umfragen."] = "Aún no hay encuestas."
T["Noch keine bekannt - sobald jemand mit Oasis eine Quest fuer diesen Dungeon hat, steht sie hier."] = "Aún no se conoce ninguna – en cuanto alguien con Oasis tenga una misión para esta mazmorra, aparecerá aquí."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff in der Uebersicht ueber '+' zum Katalog hinzu."] = "Todavía vacío. Siéntate en una fogata y añade\nel buff en la vista general con '+' al catálogo."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff rechts ueber '+' zum Katalog hinzu."] = "Todavía vacío. Siéntate en una fogata y añade\nel buff a la derecha con '+' al catálogo."
