T["Alle: Nie vor oder hinter Onyxia stehen (Atem/Schwanz).\nPhase 2 ab 65%: Feuerbaellen ausweichen, Welpen sofort umhauen.\nPhase 3 ab 40%: Furcht - Totem der Erdung und Furchtschutz bereit.\nTank: Onyxia mit dem Ruecken zur Wand, Kopf weg vom Raid.\nTank: Phase 3 sofort Aggro zurueckholen.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: Erst nach 3 Rueckenangriffen des Tanks voll loslegen.\nDD: Phase 2: Welpen vor Onyxia."] = "Todos: no os pongáis nunca delante ni detrás de Onyxia (aliento/cola).\nFase 2 desde el 65%: esquivad las bolas de fuego, matad a las crías al instante.\nFase 3 desde el 40%: miedo - Tótem de derribo y Custodia de miedo preparados.\nTanque: Onyxia de espaldas a la pared, cabeza lejos de la banda.\nTanque: en la fase 3 recupera la amenaza al instante.\nSanadores: el tanque tiene prioridad, en la fase 2 separaos.\nDPS: dad caña solo tras 3 ataques por la espalda del tanque.\nDPS: fase 2: crías antes que Onyxia."
T["Alle: Schwarm-Ziel: rauslaufen.\nTank: Infernal-Tank abseits.\nHeiler: Schlaf entfernen, wo moeglich.\nDD: Infernals ignorieren, alles auf den Boss."] = "Todos: objetivo del enjambre: salid fuera.\nTanque: tanque de infernales aparte.\nSanadores: quitad el sueño donde se pueda.\nDPS: ignorad a los infernales, todo al jefe."
T["Alle: Tod und Verfall sofort verlassen.\nTank: Mitte halten, bei Frostnova nicht bewegen.\nHeiler: Eisblock-Ziel schnell hochheilen.\nDD: Fernkampf weit verteilt (Eispfeil-Kette)."] = "Todos: salid de Muerte y descomposición al instante.\nTanque: mantén el centro, no te muevas con Nova de Escarcha.\nSanadores: curad rápido al objetivo del bloque de hielo.\nDPS: a distancia, bien separados (cadena de Descarga de Escarcha)."
