T["Automatisch: Oasis legt alle 10 Minuten und beim Ausloggen einen Schnappschuss in den Gespeicherten Variablen ab (WTF/Account/<Konto>/SavedVariables/Oasis.lua). Das Programm Tools/oasis_export.py liest die Datei, macht JSON daraus und kann es an eure Weboberflaeche schicken. Addons haben keinen Internetzugriff - das ist der sichere Weg."] = "Automático: Oasis guarda cada 10 minutos y al cerrar sesión una instantánea en las variables guardadas (WTF/Account/<Cuenta>/SavedVariables/Oasis.lua). El programa Tools/oasis_export.py lee el archivo, lo convierte en JSON y puede enviarlo a vuestra web. Los accesorios no tienen acceso a internet - esta es la vía segura."
