T["Den Talentbaum dieser Klasse kann WoW hier nicht anzeigen. Der Export-Text laesst sich unten kopieren."] = "WoW no puede mostrar aquí el árbol de talentos de esta clase. El texto de exportación se puede copiar abajo."
T["Den ganzen Verlauf mit %s loeschen? Gemerkte Nachrichten gehen mit."] = "¿Borrar todo el historial con %s? Los mensajes guardados también se borran."
T["Der Auftrag geht an alle Handwerker mit diesem Rezept - wer Zeit hat, nimmt ihn an."] = "El encargo va a todos los artesanos con esta receta - quien tenga tiempo lo acepta."
T["Der Auftrag wird fuer alle zurueckgezogen."] = "El encargo se retira para todos."
T["Der Auftraggeber bekommt Bescheid, dass es fertig ist."] = "El cliente recibe el aviso de que está terminado."
T["Der Auftraggeber bekommt Bescheid."] = "El cliente recibe el aviso."
T["Der Basar ist leer"] = "El bazar está vacío"
T["Der Brachland-Chat mit seinen Spruechen"] = "El chat de Los Baldíos con sus frases"
T["Der Client liefert gerade keine Fertigkeiten - nach dem Einloggen kurz warten."] = "El cliente no entrega habilidades ahora mismo - espera un poco tras conectarte."
T["Der Dungeonkompass: welcher Dungeon passt, was droppt dort fuer dich."] = "La brújula de mazmorras: qué mazmorra encaja y qué cae allí para ti."
T["Der Gegner stand nicht vor dir. Er stand hinter dir. Die ganze Zeit."] = "El enemigo no estaba delante de ti. Estaba detrás. Todo el tiempo."
T["Der Gruppenanfuehrer kann dich zum Assistenten machen."] = "El líder del grupo puede hacerte asistente."
T["Der Kampf war erst gesperrt und wurde nachtraeglich ausgewertet."] = "El combate estaba bloqueado y se evaluó después."
T["Der Knopf laesst sich nicht mehr mit der Maus verschieben"] = "El botón ya no se puede mover con el ratón"
T["Der Link gilt fuer alle Leitungen."] = "El enlace vale para todos los responsables."
T["Der Markt nutzt Preise aus dem AH-Addon Midas. Sobald du oder jemand aus der Gilde mit Midas im AH scannt, schaltet sich diese Seite frei."] = "El mercado usa precios del accesorio de subasta Midas. En cuanto tú o alguien de la hermandad escanee la casa de subastas con Midas, esta página se desbloquea."
T["Der Mitschnitt der Spielzeiten ist aus. Schalte ihn ein, dann lernt Oasis mit jedem Abend dazu."] = "El registro de horas de juego está desactivado. Actívalo y Oasis aprenderá con cada tarde."
T["Der Oasis-Rang ist der Gilden-Rang von Oasis - er steigt durch Zusammenspielen, Helfen, Handwerk, Termine und Abzeichen."] = "El rango de Oasis es el rango de hermandad de Oasis - sube jugando juntos, ayudando, con artesanía, citas e insignias."
T["Der Online-Sound dieser Person ist bei dir aus."] = "Tienes desactivado el sonido de conexión de esta persona."
T["Der Rand des Oasis-Fensters leuchtet in deiner Farbe"] = "El borde de la ventana de Oasis brilla en tu color"
T["Der Ring zeigt, wer ohne offene Punkte ist."] = "El anillo muestra quién no tiene puntos pendientes."
T["Der Steinfresser"] = "El Devorapiedras"
T["Der Termin liegt in der Vergangenheit."] = "La cita está en el pasado."
