T["Die Bank besucht. Mal kurz nachzaehlen."] = "Visitaste el banco. A recontar un momento."
T["Die Bannliste ist leer."] = "La lista de baneos está vacía."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde /target eingegeben."] = "Oasis había tocado la entrada del chat (p. ej. botón 'Susurrar') y después se escribió /target."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "Oasis había tocado la entrada del chat (p. ej. botón 'Susurrar') y después se escribió allí un comando /cast."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde /focus eingegeben."] = "Oasis había tocado la entrada del chat y después se escribió /focus."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde ein Zauber-Befehl eingegeben."] = "Oasis había tocado la entrada del chat y después se escribió un comando de hechizo."
T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "Los mapas de mazmorra no tienen coordenadas. Haz clic aquí y luego en el punto del mapa donde estás ahora. Hecho en dos puntos muy alejados, Oasis te muestra a ti y a tu grupo en el mapa - para toda la hermandad."
T["Die Gilde bekommt Bescheid"] = "La hermandad recibe el aviso"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "La hermandad ve a quién respondes. Por defecto: desactivado"
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "La hermandad ve tu fuego %d minutos en el mapa."
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "La hermandad ve en la crónica lo que has logrado"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "La hermandad no busca nada de esta mazmorra ahora mismo."
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "La hermandad aún no reparte puntos de botín - tus valores aparecerán cuando la dirección de banda inicie una banda."
T["Die Gildenbank wurde noch nicht gelesen"] = "El banco de hermandad aún no se ha leído"
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "La dirección de hermandad nombra líderes y asistentes de banda en Corona > Módulos > Bandas y botín (nombres o desde un rango de hermandad). En una banda en curso cuentan también el líder y los asistentes de banda."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "La dirección de hermandad nombra líderes de banda en Corona > Módulos > Bandas y botín. En una banda en curso cuentan también el líder y los asistentes de banda."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "La dirección de hermandad nombra líderes de banda en Corona > Módulos > Bandas y botín. En una banda en curso cuenta también el líder de banda."
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "La dirección de hermandad solo permite búsquedas de grupo desde un rango superior."
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "La dirección de hermandad solo permite encuestas desde un rango superior."
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "La dirección de hermandad ha desactivado la búsqueda de compañeros."
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "La dirección de hermandad ha desactivado las invitaciones abiertas - reta a alguien directamente."
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "La dirección de hermandad decide en Corona > Módulos qué rangos pueden hacerlo."
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "El buscador de hermandades de WoW ayuda a encontrar - neutral, sin publicidad."
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "El límite solo lo fija el maestro de la hermandad. Rango 1 = maestro de la hermandad."
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "Los botones escriben el comando en la línea de chat - solo se ejecuta al pulsar Intro."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "Los atajos también están en las asignaciones de teclas de WoW, en AddOns > Oasis. Esc cierra la ventana de Oasis (en combate no - ahí Esc es del juego)."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "Los atajos también están en las asignaciones de teclas de WoW, en AddOns > Oasis. Esc cierra la ventana de Oasis mientras hayas hecho clic en ella lo último."
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "La barra se repliega hacia arriba; lleva el ratón al borde superior y baja (solo si está acoplada arriba)"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "La fila de reservas solo aparece si estás en un grupo o una banda"
T["Die Waechter der Sande"] = "Los Guardianes de las Arenas"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "Abriste el mapa del mundo. ¿Dónde estaba el norte?"
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "La barra real de arriba muestra cada cambio al instante"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "Los primeros 20 de aguante dan 1 cada uno; cada punto más, 10 de salud."
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "La mayoría de carreras de espíritu de la hermandad. El cementerio tiene un banco con tu nombre."
T["Die meisten Screenshots der Gilde"] = "La mayoría de capturas de pantalla de la hermandad"
T["Die meisten Tode der letzten 7 Tage"] = "La mayoría de muertes de los últimos 7 días"
T["Die meisten vollen Taschen der Gilde"] = "La mayoría de bolsas llenas de la hermandad"
T["Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "El anuncio más reciente se queda 3 días arriba en el resumen."
T["Die vergessenen Teiche"] = "Los estanques olvidados"
T["Diese Abzeichen zeigt deine Profilkarte zuerst - bei dir und bei der Gilde."] = "Tu tarjeta de perfil muestra primero estas insignias - para ti y para la hermandad."
