T["Diese Regel gibt es schon."] = "Esta regla ya existe."
T["Diese Seiten stehen als kleine Knoepfe in der eingeklappten Oasis-Leiste - ein Klick oeffnet sie direkt."] = "Estas páginas aparecen como botones pequeños en la barra plegada de Oasis - un clic las abre directamente."
T["Diese Sitzung: %d EP in %s"] = "Esta sesión: %d PE en %s"
T["Diese Sprache gilt nach dem naechsten /reload - hier klicken zum Neuladen."] = "Este idioma se aplica tras el próximo /reload - haz clic aquí para recargar."
T["Diese Taktik ist noch leer."] = "Esta táctica aún está vacía."
T["Diese Woche ist noch alles offen - wer macht den Anfang?"] = "Esta semana aún está todo abierto - ¿quién empieza?"
T["Diese Woche:"] = "Esta semana:"
T["Dieser Client hat keine Sammlungs-Schnittstelle. /oa probe sammlung zeigt Details."] = "Este cliente no tiene interfaz de colecciones. /oa probe sammlung muestra detalles."
