T["Dieser Client meldet keine seltenen Gegner (Schnittstelle fehlt). /oa probe rares zeigt Details."] = "Este cliente no informa de enemigos raros (falta la interfaz). /oa probe rares muestra detalles."
T["Dir fehlt nichts, was die Gilde hat - stark!"] = "No te falta nada que tenga la hermandad - ¡genial!"
T["Dir selbst etwas zugefluestert. Wer sonst hoert dir so gut zu?"] = "Te susurraste a ti mismo. ¿Quién más te escucha tan bien?"
