T["Neuer Versuch laeuft - in 5 Sekunden nochmal /oa netz eingeben."] = "Nuevo intento en curso - vuelve a escribir /oa netz en 5 segundos."
T["Neuer Wunsch eines anderen und du hast das Item dabei"] = "Otro añade un deseo y tú llevas el objeto"
T["Neues Event"] = "Nuevo evento"
