T["Neues Gespraech"] = "Nueva conversación"
T["Neues Gildenziel"] = "Nuevo objetivo de hermandad"
T["Neues Stufen-Abzeichen freigeschaltet"] = "Nueva insignia de nivel desbloqueada"
T["Neues Ziel"] = "Nuevo objetivo"
T["Neueste"] = "Más recientes"
T["Neuigkeiten am Knopf"] = "Novedades en el botón"
T["Neuigkeiten-Zahl"] = "Número de novedades"
T["Neuigkeiten-Zahlen"] = "Contadores de novedades"
