T["Neuigkeiten: %s"] = "Novedades: %s"
T["Neutral"] = "Neutral"
T["Nicht dein Levelbereich"] = "No es tu rango de nivel"
T["Nicht freigeschaltet"] = "Sin acceso"
T["Nicht fuer deine Klasse:"] = "No para tu clase:"
T["Nicht genug Mana, Wut oder Energie. Erst trinken, dann draufhauen."] = "No hay suficiente maná, ira o energía. Primero bebe, luego pega."
T["Nicht in einer Gruppe."] = "No estás en un grupo."
T["Nicht in einer Gruppe. Sobald du in einer Gruppe oder einem Raid bist, siehst du hier, wem welcher Buff fehlt."] = "No estás en un grupo. En cuanto estés en un grupo o banda, verás aquí a quién le falta qué beneficio."
T["Nicht mehr fragen"] = "No volver a preguntar"
T["Nicht mehr merken"] = "Dejar de recordar"
T["Nicht tragbar"] = "No equipable"
T["Nichts angeheftet - Rechtsklick auf ein Gespraech: Anheften."] = "Nada fijado - clic derecho en una conversación: Fijar."
T["Nichts davon liegt in der Gildenbank."] = "Nada de esto está en el banco de hermandad."
T["Nichts erkannt - ist das der CSV-Export von softres.it?"] = "No se ha reconocido nada - ¿es la exportación CSV de softres.it?"
T["Nichts gefunden"] = "No se ha encontrado nada"
T["Nichts gefunden - andere Filter probieren?"] = "No se ha encontrado nada - ¿probar otros filtros?"
T["Nichts gefunden - andere Suche probieren."] = "No se ha encontrado nada - prueba otra búsqueda."
T["Nichts gefunden - andere Suche probieren?"] = "No se ha encontrado nada - ¿probar otra búsqueda?"
T["Nichts in deinem Levelbereich - schalte auf Alle oder tippe ein Ziel ein."] = "Nada en tu rango de nivel - cambia a Todos o escribe un destino."
T["Nichts in der Bank steht gerade auf einer Gesucht-Liste."] = "Nada del banco está ahora en una lista de buscados."
T["Nichts in dieser Kategorie"] = "Nada en esta categoría"
T["Nichts passt zu diesen Filtern."] = "Nada coincide con estos filtros."
T["Nichts passt zum Filter"] = "Nada coincide con el filtro"
T["Nichts verworfen."] = "Nada descartado."
T["Nichts zu pruefen."] = "Nada que comprobar."
T["Nie"] = "Nunca"
T["Niemand aus dem Vorschlag ist online."] = "Nadie de la sugerencia está conectado."
T["Niemand frei: alle passenden Charaktere sind gebunden, zu niedrig oder nicht freigeschaltet."] = "Nadie libre: todos los personajes adecuados están ligados, son de nivel bajo o no tienen acceso."
T["Niemand gestorben - sauber gespielt."] = "Nadie ha muerto - limpio."
T["Niemand gestorben."] = "Nadie ha muerto."
T["Niemand in der Gilde hat diesen Beruf eingetragen."] = "Nadie de la hermandad ha registrado esta profesión."
T["Niemand in der Gilde hat etwas mit diesem Namen."] = "Nadie de la hermandad tiene nada con ese nombre."
T["Niemand in der Gruppe kann ihn geben"] = "Nadie del grupo puede darlo"
T["Niemand in diesem Filter - sehr gut!"] = "Nadie en este filtro - ¡muy bien!"
T["Niemand ist so lange offline."] = "Nadie lleva tanto tiempo desconectado."
T["Niemand sonst in der Gilde"] = "Nadie más en la hermandad"
T["Niemand steht kurz vor Respektvoll oder Ehrfuerchtig (ab 75 %)."] = "Nadie está cerca de Venerado o Exaltado (a partir del 75 %)."
T["Niemand. Stummschalten geht per Rechtsklick auf einen Namen im Gildenchat."] = "Nadie. Silencia a alguien con clic derecho en un nombre del chat de hermandad."
T["Ninja-Markierung entfernen"] = "Quitar marca de ninja"
T["Noch aus"] = "Aún desactivado"
T["Noch gesperrt"] = "Aún bloqueado"
T["Noch hat niemand Material beigetragen."] = "Aún nadie ha aportado material."
T["Noch kein Highlight - die Woche ist jung."] = "Aún no hay nada destacado - la semana es joven."
T["Noch kein Kampf ausgewertet"] = "Aún no se ha evaluado ningún combate"
T["Noch kein Muster - dafuer braucht es mehrere Versuche."] = "Aún no hay patrón - para eso hacen falta varios intentos."
T["Noch kein Ready-Check"] = "Aún no hay comprobación de listos"
T["Noch kein Ready-Check gelaufen."] = "Aún no se ha hecho ninguna comprobación de listos."
T["Noch kein Scan - sobald jemand mit Midas scannt, stehen hier Schnaeppchen."] = "Aún no hay escaneo - en cuanto alguien escanee con Midas, aquí aparecerán gangas."
T["Noch kein Termin - melde dein Interesse, dann weiss die Raidleitung, wann es passt."] = "Aún no hay cita - indica tu interés y así los líderes de banda sabrán cuándo encaja."
T["Noch kein Tod - weiter so!"] = "Aún ninguna muerte - ¡sigue así!"
T["Noch kein Tod eines seltenen Gegners erfasst."] = "Aún no se ha registrado la muerte de ningún enemigo raro."
T["Noch keine Abklingzeiten geteilt - wer Transmutation, Mondstoff oder einen Salzstreuer hat, erscheint hier."] = "Aún no se han compartido tiempos de reutilización - quien tenga Transmutación, Tela lunar o un Salero aparece aquí."
T["Noch keine Abzeichen"] = "Aún no hay insignias"
T["Noch keine Ausruestung bekannt - Spieler in der Naehe anvisieren und betrachten (Oasis betrachtet Mitspieler in der Gruppe automatisch)."] = "Aún no se conoce el equipo - selecciona e inspecciona a jugadores cercanos (Oasis inspecciona automáticamente a los compañeros de grupo)."
T["Noch keine Berufe gelernt."] = "Aún no has aprendido profesiones."
T["Noch keine Beute aus diesem Dungeon im Gilden-Log."] = "Aún no hay botín de esta mazmorra en el registro de la hermandad."
T["Noch keine Beute erfasst"] = "Aún no se ha registrado botín"
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "Aún no hay aspirantes. Introduce un nombre arriba - clic en el estado lo avanza."
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "Aún no hay datos - el equipo llega con la próxima sincronización de los usuarios de Oasis."
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "Aún no hay datos - los miembros envían su medición cada 15 min (desde esta versión)."
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Aún no hay datos - abre una vez la ventana de colecciones o lleva monturas y mascotas en la bolsa. En cuanto haya miembros de la hermandad con Oasis conectados, aparecerán aquí."
T["Noch keine Daten von der Gilde."] = "Aún no hay datos de la hermandad."
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "Aún no hay datos. En cuanto los miembros de la hermandad se conecten con Oasis, sus bloqueos de banda aparecerán aquí."
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "Aún no se han registrado recorridos de mazmorra."
T["Noch keine Dungeons geplant."] = "Aún no hay mazmorras planificadas."
T["Noch keine Eintraege."] = "Aún no hay entradas."
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "Aún no has usado emojis - los favoritos de la selección de emojis aparecen aquí."
T["Noch keine Favoriten - Diamant anklicken."] = "Aún no hay favoritos - haz clic en el diamante."
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "Aún no hay favoritos - estrella o clic derecho en un sonido."
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "Aún no hay favoritos.\nClic derecho en un emoji lo guarda aquí."
T["Noch keine Fluesternachrichten."] = "Aún no hay susurros."
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "Aún no hay susurros. ¡Escribe a alguien de la hermandad!"
T["Noch keine Fraktionen entdeckt."] = "Aún no has descubierto facciones."
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "Aún no hay objetivos de hermandad. Crea el primero - p. ej. un arma legendaria o material para la banda."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "Aún no hay informes de combate. Tras el primer combate contra jefe aparece aquí cada intento - con línea temporal de muertes y patrones recurrentes."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "Aún no hay informes de combate. Tras el primer combate contra jefe aparece aquí cada intento."
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "Aún no hay candidatos. Juega con gente de fuera de la hermandad - quien no tenga hermandad y esté bien valorado aparecerá aquí."
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "Aún no hay combos.\nMayús+clic en varios emojis y luego Recordar."
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "Aún no hay contactos. Agrúpate con otros usuarios de Oasis - Oasis los recordará aquí, incluso sin hermandad."
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "Aún no hay hitos. Sube de nivel, aprende profesiones - aquí nace tu historia."
T["Noch keine Meldungen aus der Gilde."] = "Aún no hay informes de la hermandad."
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "Aún no hay momentos - tú juega, Oasis toma nota."
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "Aún no hay mensajes en el chat de oficiales. Todo lo que se escriba a partir de ahora en el canal /o aparecerá aquí."
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "Aún no hay posiciones - el mapa se llena en cuanto haya miembros con Oasis en marcha."
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "Aún no hay precios. En cuanto alguien escanee la casa de subastas con Midas, aparecerán aquí."
T["Noch keine Profile gespeichert."] = "Aún no hay perfiles guardados."
T["Noch keine Punkte"] = "Aún no hay puntos"
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "Aún no se han registrado días de banda. El líder de banda (con Oasis) los anota automáticamente en cada muerte de jefe."
T["Noch keine Regeln"] = "Aún no hay reglas"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "Aún no hay reglas. Usa una plantilla rápida o crea una propia arriba."
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "Aún no hay datos de reputación. Llegan automáticamente en cuanto haya miembros con Oasis conectados."
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Aún no se ha compartido ninguna colección. Aparecerán aquí en cuanto haya miembros de la hermandad con Oasis conectados."
T["Noch keine Sets."] = "Aún no hay conjuntos."
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "Aún no hay avistamientos. En cuanto alguien con Oasis vea un enemigo raro, aparecerá aquí."
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "Aún no se conocen horarios de juego. Oasis aprende cada noche que estás conectado - y adopta los perfiles de los demás."
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "Aún no hay búsqueda. Introduce niveles y pulsa \"Buscar\" - se ocultan los jugadores con hermandad."
T["Noch keine Taktiken."] = "Aún no hay tácticas."
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "Aún no hay tácticas. Los líderes de banda pueden crear una táctica breve por jefe - todos la ven aquí y se muestra al seleccionarlo."
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "Aún no se conocen talentos. Los miembros con Oasis los comparten automáticamente; otros jugadores: selecciona e inspecciona (clic derecho > Inspeccionar) o vuelve a abrir aquí con objetivo."
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "Aún no hay asignaciones - aparecerán aquí en cuanto los líderes de banda repartan botín."
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "Aún no hay valores - tras el próximo combate aparecerá aquí quién va en cabeza."
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "Aún no hay días preferidos - toca cuándo puedes."
T["Noch keine Wunschtage gemeldet."] = "Aún no se han indicado días preferidos."
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "Aún no hay objetivos. Crea uno arriba - Oasis lo marcará automáticamente."
T["Noch keine Zusagen - sei der Erste!"] = "Aún no hay inscripciones - ¡sé el primero!"
T["Noch keine eigene Beute"] = "Aún no hay botín propio"
T["Noch keine eigene Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "Aún no se ha registrado botín propio (desde calidad 'Raro', ajustable)."
T["Noch nicht angemeldet - waehle unten deine Rolle"] = "Aún no inscrito - elige tu rol abajo"
T["Noch nicht bereit"] = "Aún no listo"
T["Noch nicht fuer die Gilde uebernommen:"] = "Aún no aplicado para la hermandad:"
T["Noch nicht kalibriert - Kalibrieren?"] = "Aún no calibrado - ¿calibrar?"
T["Noch nichts auf der Wunschliste.\nTrag oben ein, was du brauchst - alle mit Oasis sehen es im Tooltip und beim Looten."] = "Aún no hay nada en la lista de deseos.\nAñade arriba lo que necesitas - todos con Oasis lo ven en la descripción y al despojar."
T["Noch nichts aufgezeichnet."] = "Aún no se ha registrado nada."
T["Noch nichts benutzt."] = "Aún no se ha usado nada."
T["Noch nichts blockiert. Sobald WoW Oasis blockiert, steht hier welche Funktion und was Oasis kurz vorher gemacht hat."] = "Aún no se ha bloqueado nada. En cuanto WoW bloquee Oasis, aquí aparecerá qué función y qué hizo Oasis justo antes."
T["Noch nichts eingelesen"] = "Aún no se ha leído nada"
T["Noch nichts geangelt."] = "Aún no has pescado nada."
T["Noch nichts gemerkt - Rechtsklick auf eine Nachricht: Nachricht merken."] = "Aún no has guardado nada - clic derecho en un mensaje: Guardar mensaje."
T["Noch nichts passiert - zieht los und schreibt Geschichte!"] = "Aún no ha pasado nada - ¡salid y haced historia!"
T["Noch nichts reserviert"] = "Aún no hay nada reservado"
T["Noch nichts reserviert - ein Item pro Termin."] = "Aún no hay nada reservado - un objeto por cita."
T["Noch nichts reserviert."] = "Aún no hay nada reservado."
T["Noch nichts verkauft."] = "Aún no has vendido nada."
T["Noch nichts verteilt. Sobald eine Regel greift, steht es hier."] = "Aún no se ha repartido nada. En cuanto se aplique una regla, aparecerá aquí."
T["Noch nie direkt mit dir abgeglichen"] = "Nunca sincronizado directamente contigo"
T["Noch niemand angefluestert."] = "Aún no has susurrado a nadie."
T["Noch niemand aus der Gilde hat es uebrig."] = "Aún no le sobra a nadie de la hermandad."
T["Noch niemand aus der Gilde mit deiner Spezialisierung teilt seine Talente (Oasis-Nutzer teilen automatisch)."] = "Aún nadie de la hermandad con tu especialización comparte sus talentos (los usuarios de Oasis los comparten automáticamente)."
T["Noch niemand gegangen, seit Oasis mitschreibt."] = "Nadie se ha ido desde que Oasis registra."
T["Noch niemand gemeldet - sei der Erste!"] = "Aún no se ha apuntado nadie - ¡sé el primero!"
T["Noch niemand sonst kennt das Rezept."] = "Nadie más conoce aún la receta."
T["Noch niemand teilt seine Handelsbilanz."] = "Aún nadie comparte su balance comercial."
T["Noch niemand teilt seine Handelsbilanz. Unten 'Bilanz teilen' einschalten - dann geht's los."] = "Aún nadie comparte su balance comercial. Activa 'Compartir balance' abajo - y empezamos."
T["Noch teilt niemand mit Oasis handelbare Teile. Je mehr Mitglieder Oasis nutzen, desto voller wird es hier."] = "Aún nadie comparte piezas comerciables con Oasis. Cuantos más miembros usen Oasis, más se llenará esto."
T["Noch zu uebergeben"] = "Pendiente de entregar"
T["Noch zu wenig Daten fuer eine Stosszeit"] = "Aún pocos datos para una hora punta"
T["Normal"] = "Normal"
T["Normal meldet Oasis nur Suchen, die du selbst noch offen hast"] = "Normalmente Oasis solo avisa de búsquedas que tú mismo tienes abiertas"
T["Notiz (Klasse, Kontakt, Eindruck ...)"] = "Nota (clase, contacto, impresión ...)"
T["Notiz an den Plundermeister (optional)"] = "Nota para el maestro despojador (opcional)"
T["Notiz der Gildenleitung"] = "Nota de los líderes de la hermandad"
T["Notiz von %s: %s"] = "Nota de %s: %s"
T["Notiz zu %s"] = "Nota sobre %s"
T["Notiz zur Person"] = "Nota sobre la persona"
T["Notiz zur Suche (Zeit, Treffpunkt) ..."] = "Nota para la búsqueda (hora, punto de encuentro) ..."
T["Notizen sehen und schreiben nur Offiziere."] = "Solo los oficiales ven y escriben notas."
T["Nur %s"] = "Solo %s"
T["Nur Abende vorschlagen"] = "Sugerir solo noches"
T["Nur Banner und drei Spalten (wer ist online, was passiert, als Naechstes) - ohne Kacheln und Highlight-Zeile"] = "Solo el banner y tres columnas (quién está conectado, qué pasa, lo siguiente) - sin mosaicos ni línea destacada"
T["Nur Dungeons, deren Beute besser ist als deine angelegte Ausruestung."] = "Solo mazmorras cuyo botín supera tu equipo puesto."
T["Nur Eintraege dieser Person"] = "Solo entradas de esta persona"
T["Nur Farbverlauf"] = "Solo degradado"
T["Nur Gegner im Kampf"] = "Solo enemigos en combate"
T["Nur Gildenleitung"] = "Solo líderes de la hermandad"
T["Nur Gruppenquests beruecksichtigen"] = "Solo misiones de grupo"
T["Nur Lagerfeuer in meinem Gebiet melden"] = "Avisar solo de hogueras en mi zona"
T["Nur Mains ab Level"] = "Solo principales a partir del nivel"
T["Nur Mitglieder bis zu diesem Rang duerfen eine Gruppensuche starten (10 = alle)."] = "Solo los miembros hasta este rango pueden iniciar una búsqueda de grupo (10 = todos)."
T["Nur Mitglieder bis zu diesem Rang duerfen eine neue Umfrage starten (10 = alle)."] = "Solo los miembros hasta este rango pueden iniciar una encuesta nueva (10 = todos)."
T["Nur Mitglieder mit Oasis. Geteilt werden offene Questitems, uebrige Questitems und teilbare Quests."] = "Solo miembros con Oasis. Se comparten objetos de misión pendientes, objetos de misión sobrantes y misiones compartibles."
T["Nur Oasis-Spieler"] = "Solo jugadores de Oasis"
T["Nur Oasis-Spieler: jeder sieht sie in seiner eigenen Sprache."] = "Solo jugadores de Oasis: cada uno lo ve en su propio idioma."
T["Nur Offiziere und Gildenleitung sehen diesen Kanal (/o)."] = "Solo los oficiales y los líderes de la hermandad ven este canal (/o)."
T["Nur Plundermeister, Anfuehrer oder Assistenten koennen verteilen."] = "Solo el maestro despojador, el líder o los ayudantes pueden repartir."
T["Nur Rezepte, die du selbst kannst"] = "Solo recetas que conoces"
T["Nur Rezepte, die gerade jemand online herstellen kann"] = "Solo recetas que alguien conectado puede fabricar ahora"
T["Nur Upgrades"] = "Solo mejoras"
T["Nur an die eigene Gruppe, fuer die Dungeon-Karte"] = "Solo para tu grupo, para el mapa de mazmorra"
T["Nur ansehen - bearbeiten: Leitung, Schlachtzugsleiter, Raid-Assistenten"] = "Solo ver - editar: líderes, líderes de banda, ayudantes de banda"
T["Nur ansehen - zeichnen darf der Raidleiter"] = "Solo ver - dibuja el líder de banda"
T["Nur auf diesem PC"] = "Solo en este PC"
T["Nur ausgeblendet - klick hier, um zurueckzukehren."] = "Solo oculto - haz clic aquí para volver."
T["Nur bei dir"] = "Solo para ti"
T["Nur bei dir gespeichert"] = "Guardado solo para ti"
T["Nur bei gleicher Klasse und Spezialisierung."] = "Solo con la misma clase y especialización."
T["Nur das Noetigste"] = "Solo lo esencial"
T["Nur der Gildenmeister kann das aendern."] = "Solo el maestro de la hermandad puede cambiar esto."
T["Nur der Gildenmeister, hoechstens 10 Raenge."] = "Solo el maestro de la hermandad, como máximo 10 rangos."
T["Nur der Gruppenleiter kann eine Suche starten."] = "Solo el líder del grupo puede iniciar una búsqueda."
T["Nur der Gruppenleiter kann suchen"] = "Solo el líder del grupo puede buscar"
T["Nur die Gildenleitung kann das aendern."] = "Solo los líderes de la hermandad pueden cambiar esto."
T["Nur die Gildenleitung kann die Deathroll-Rangliste zuruecksetzen."] = "Solo los líderes de la hermandad pueden reiniciar la clasificación de Deathroll."
T["Nur die wichtigsten Bereiche sind an."] = "Solo las secciones más importantes están activadas."
T["Nur diese Person hoert ihn (wenn sie Oasis hat)."] = "Solo lo oye esta persona (si tiene Oasis)."
T["Nur diesen Abschnitt posten"] = "Publicar solo esta sección"
T["Nur fehlende"] = "Solo los que faltan"
T["Nur fuer Anfuehrer und Assistenten"] = "Solo para líder y ayudantes"
