T["Oasis fasst deine Charaktere in der Gilde zu einem Spieler zusammen. Spaeter aenderbar unter Einstellungen > Profil & Sichern."] = "Oasis agrupa tus personajes de la hermandad en un solo jugador. Se puede cambiar luego en Ajustes > Perfil y copia de seguridad."
