T["Oasis ist bereit"] = "Oasis está listo"
T["Oasis kann sehr viel. Waehle, was du nutzen willst - der Rest bleibt erstmal aus und laesst sich jederzeit unter 'Entdecken' einschalten."] = "Oasis hace muchas cosas. Elige lo que quieres usar - el resto queda desactivado por ahora y se puede activar en cualquier momento en 'Descubrir'."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - auch in Instanzen."] = "Oasis lee tras cada combate el medidor de daño integrado de Blizzard - también en instancias."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - das Kampflog ist in WoW Forever fuer Addons gesperrt. Mitspieler brauchen Oasis ab 0.5.577. Werte, die Blizzard verschluesselt (z.B. in Instanzen), zaehlen nicht."] = "Oasis lee tras cada combate el medidor de daño integrado de Blizzard - el registro de combate está bloqueado para addons en WoW Forever. Los compañeros necesitan Oasis 0.5.577 o superior. Los valores que Blizzard cifra (p. ej. en instancias) no cuentan."
