T["Wer"] = "Quién"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "Quien envía datos que los demás rechazan (sin permisos, autor falsificado, entradas inventadas). Un Oasis sin modificar casi nunca hace esto - es un indicio, no una prueba."
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "Quien muestre interés aparece aquí en un puesto adecuado. Cuando haya un evento, te apuntas directamente en su tarjeta."
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "Quién de la hermandad tiene el objeto en su lista de deseos"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "Quién ve la sección en la navegación (la dirección de la hermandad siempre lo ve todo)"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "Quién ha dejado la hermandad o ha sido expulsado. Si alguien vuelve, Oasis avisa a la dirección de la hermandad."
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "Quién ve la corona de arriba. Sin permisos aparece gris y solo abre una vista previa."
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "Quién puede fijar un mensaje arriba en el chat de hermandad"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "Aún no se sabe quién puede invitar - conéctate una vez con tu principal y Oasis recordará a la dirección de la hermandad."
