T["Werte nur zur Info"] = "Estadísticas solo informativas"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "Estadísticas, anuario, objetivo diario, récords y aventuras de tu personaje."
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "Estadísticas: +sanación, intelecto, espíritu, regen. de maná;Arma: bastón o arma de una mano + mano izquierda con sanación;Sanar: Rejuvenecimiento y Recrecimiento por adelantado, Toque de sanación para golpes fuertes;Consejo: Estimular para maná, Renacer para sanadores caídos"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "Estadísticas: +sanación, intelecto, crítico con hechizos (Iluminación devuelve maná), regen. de maná;Arma: arma de una mano + mano izquierda/escudo con sanación;Sanar: Destello de Luz para daño pequeño, Luz Sagrada (rango bajo) para golpes fuertes;Consejo: reparte bendiciones, Protección divina si atraes amenaza"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "Estadísticas: +sanación, regen. de maná (MP5), intelecto - el espíritu aporta poco;Arma: arma de una mano + escudo con sanación;Sanar: Sanación en cadena para grupos, Ola de sanación (rango bajo) para el tanque;Consejo: pon el Tótem Fuente de maná, Escudo de tierra en el tanque"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "Estadísticas: +sanación, espíritu (Meditación: regeneración también al lanzar), intelecto, regen. de maná;Arma: bastón o arma de una mano + mano izquierda con sanación, varita;Sanar: Renovar y Palabra de poder: escudo por adelantado, Sanación superior (rango bajo) para el tanque;Consejo: Rezo de sanación para el grupo, Desvanecerse si tienes amenaza"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "Estadísticas: armadura (la forma de oso la multiplica), aguante, agilidad (esquivar + armadura);Arma: el daño da igual - solo cuentan las estadísticas (bastón/arma de asta con aguante);Rotación: Magullar, Flagelo para grupos, Rugido desmoralizador;Consejo: fuerza para más amenaza, Enfurecer al empezar"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "Estadísticas: fuerza (1 punto = 2 PA), agilidad (PA + crítico), crítico, golpe hasta +9 %;Arma: el daño da igual - solo cuentan las estadísticas;Rotación: Zarpa/Triturar para puntos de combo, luego Mordedura feroz;Consejo: powershift (volver a la forma) para energía, abrir desde sigilo"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "Estadísticas: fuerza (1 punto = 2 PA), crítico (activa Ráfaga = golpes más rápidos), golpe hasta +9 %;Arma: arma de dos manos lenta - Viento Furioso se activa por golpe, así que más lenta = más daño;Rotación: Arma Viento Furioso, Golpe de tormenta, Choque de tierra;Consejo: Tótem Fuerza de la tierra y Tótem Viento Furioso para el grupo"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "Estadísticas: fuerza (1 punto = 2 PA), crítico, golpe hasta +9 %;Arma: arma de dos manos lenta - sellos y Sentencia escalan por golpe;Rotación: Sello de rectitud/de orden, Sentencia, volver a poner el sello;Consejo: Consagración solo con maná suficiente, Bendición de poderío para ti"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "Estadísticas: golpe hasta +9 %, agilidad (1 PA, aprox. 29 = 1 % de crítico), PA, crítico;Arma: Combate = mano izquierda rápida, mano derecha lenta (Golpe siniestro); dagas para Puñalada;Rotación: acumula puntos de combo, mantén Hacer picadillo, luego Eviscerar;Consejo: con dos armas los golpes normales fallan más - el golpe es lo más importante"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "Estadísticas: golpe hasta +9 %, agilidad (2 PA a distancia, aprox. 53 = 1 % de crítico), PA, intelecto;Arma: arma a distancia lenta (mucho daño por disparo), arma cuerpo a cuerpo por las estadísticas;Rotación: Marca del cazador, Disparo automático, Disparo apuntado/Disparo múltiple entre medias;Consejo: alimenta a tu mascota y mantenla contenta, Trampa congelante (cuadrado) para control"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "Estadísticas: golpe hasta +9 %, fuerza (1 punto = 2 PA), crítico (aprox. 20 agilidad = 1 %);Arma: arma de dos manos lenta (Golpe mortal y Golpe heroico escalan por golpe);Rotación: genera ira, Golpe mortal / Sed de sangre, Torbellino, ira sobrante en Golpe heroico;Consejo: Grito de batalla antes del combate, Ejecutar por debajo del 20 % de salud"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "Estadísticas: defensa (440 = inmune a críticos de jefes a nivel 60), aguante, armadura, bloqueo;Arma: arma de una mano + escudo, arma rápida = más ira;Rotación: Embate con escudo/Revancha, Hender armadura en el objetivo, Golpe heroico con mucha ira;Consejo: el golpe ayuda a que Provocar y las habilidades no fallen"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "Estadísticas: defensa, aguante, armadura, luego daño con hechizos para más amenaza;Arma: arma de una mano (mejor con daño con hechizos) + escudo;Rotación: Furia justa activa, Consagración para grupos, mantén Escudo sagrado;Consejo: el maná escasea - usa Sello de sabiduría o algo de intelecto"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "Estadísticas: daño con hechizos, crítico con hechizos (Foco elemental ahorra maná), intelecto, regen. de maná;Arma: arma de una mano + escudo/mano izquierda con daño con hechizos;Rotación: Descarga de relámpagos sin parar, Cadena de relámpagos para grupos, Choque de llamas;Consejo: golpe con hechizos hasta +16 % en banda, Tótem Fuente de maná contra quedarte sin maná"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "Estadísticas: daño con hechizos, crítico con hechizos, intelecto, golpe con hechizos hasta +16 % en banda;Arma: bastón o arma de una mano + mano izquierda con daño con hechizos;Rotación: Fuego lunar + Enjambre de insectos, luego Cólera o Fuego estelar;Consejo: Estimular sobre ti cuando escasee el maná"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "Estadísticas: daño con hechizos, golpe con hechizos hasta +16 % (banda), aguante, intelecto;Arma: bastón o daga + mano izquierda con daño con hechizos, varita para el maná restante;Rotación: Corrupción + maldición, luego Descarga de las Sombras; Transfusión de vida en vez de beber;Consejo: el aguante compensa doble (Transfusión de vida, abisario/Vínculo de alma)"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "Estadísticas: daño con hechizos, golpe con hechizos hasta +16 % (banda), espíritu para maná;Arma: bastón o arma de una mano + mano izquierda con daño con hechizos;Rotación: Palabra de las Sombras: dolor, Explosión mental, Tortura mental;Consejo: Forma de las Sombras siempre activa, Abrazo vampírico cura al grupo"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "Estadísticas: daño con hechizos, luego golpe con hechizos hasta +16 % (jefes de banda), intelecto, crítico con hechizos;Arma: bastón con daño con hechizos, más una varita para el maná restante;Rotación: Descarga de Escarcha o Bola de Fuego sin parar, Evocación sin maná;Subir de nivel: intelecto y espíritu = menos pausas, en grupo oveja (luna)"
