T["Zeigt BESSER / SCHLECHTER / NICHT TRAGBAR mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Muestra MEJOR / PEOR / NO EQUIPABLE con su efecto (DPS, salud, armadura) y tabla de estadísticas. La comparación de Blizzard solo aparece con Mayús. Si nesUI está cargado con su propia comparación, Oasis no muestra nada (si no, saldría doble) - desactívala allí con /nes vergleich."
T["Zeigt Besser / Schlechter / Nicht tragbar mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Muestra Mejor / Peor / No equipable con su efecto (DPS, salud, armadura) y tabla de estadísticas. La comparación de Blizzard solo aparece con Mayús. Si nesUI está cargado con su propia comparación, Oasis no muestra nada (si no, saldría doble) - desactívala allí con /nes vergleich."
T["Zeigt Beute aus Dungeons deines Levelbereichs, die besser ist als dein angelegtes Teil."] = "Muestra botín de mazmorras de tu rango de nivel que es mejor que tu pieza equipada."
T["Zeigt ab Oasis-Rang 30 ein Juwel und ab Rang 70 einen schimmernden Namen im Oasis-Gildenchat"] = "Muestra una gema desde el rango 30 de Oasis y un nombre brillante desde el rango 70 en el chat de hermandad de Oasis"
T["Zeigt die Levelspanne der Gebiete"] = "Muestra el rango de niveles de las zonas"
T["Zeigt einen Hinweis, sobald jemand aus der Gilde einen neuen Termin anlegt"] = "Muestra un aviso en cuanto alguien de la hermandad crea un evento nuevo"
T["Zeigt im Brachland ab und zu typische Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet."] = "En los Baldíos muestra de vez en cuando frases típicas en el chat general - Chuck Norris, la mujer de Mankrik ... Solo para ti, no se envía nada."
T["Zeigt im Item-Tooltip, wer das Item fuer einen anstehenden Termin reserviert hat"] = "Muestra en la descripción del objeto quién lo ha reservado para un próximo evento"
