T["1.  Kampflog mitschreiben lassen (Einstellungen > Bereiche > Kampf-Rangliste, steht auf an).\n2.  Nach dem Spielen im Oasis-Ordner ImportCrits.bat doppelklicken.\n3.  Im Spiel /reload - dein hoechster Crit steht hier und wird mit der Gilde geteilt."] = "1.  Deja activado el registro de combate (Ajustes > Secciones > Clasificación de combate, activado por defecto).\n2.  Después de jugar, haz doble clic en ImportCrits.bat en la carpeta de Oasis.\n3.  /reload en el juego: tu crítico más alto aparece aquí y se comparte con la hermandad."
T["1. Ueberschrift"] = "1. Título"
