T["Aktiv: Meme-Sounds, Musik und Gilden-Emojis sind enthalten."] = "Activo: incluye sonidos meme, música y emojis de hermandad."
T["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "Los miembros activos por debajo de los rangos de oficial aparecen en la lista 'Ascenso' tras tantos días en el mismo rango. 0 = desactivado."
T["Aktuelles Gebiet zuerst"] = "Zona actual primero"
T["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "Todas las secciones, agrupadas por tema: hermandad, jugar juntos, banda, comercio, diversión. Haz clic en un título para plegar su grupo."
T["Alle Gebiete aufklappen"] = "Desplegar todas las zonas"
T["Alle Gebiete zuklappen"] = "Plegar todas las zonas"
T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "Todos los miembros con rango, nivel y versión de Oasis. Clic derecho en una fila: cambiar rango."
T["Alle Schriften unter der SIL Open Font License 1.1"] = "Todas las fuentes bajo la SIL Open Font License 1.1"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: Adrenalina ardiente: salir de la banda YA (vas a morir).\nAll: Recursos llenos al empezar: usarlo todo.\nTank: Fijar un orden de tanques (Adrenalina en el tanque).\nDD: Ni delante ni detrás del dragón."
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: No dejar morir a los 8 Firesworn cerca de la banda (explosión).\nTank: Cada tanque de adds aleja a su Firesworn, los brujos destierran.\nHealer: Disipar, vigilar a los tanques de adds.\nDD: Garr primero, adds solo cuando se indique."
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: Tanquear a los dos Core Ragers lejos del jefe, no matarlos.\nTank: Cambiar de tanque en Golemagg si Magma Splash acumula demasiado.\nDD: Solo a Golemagg."
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: Primero los 4 sacerdotes, se curan entre sí.\nTank: Sulfuron y los sacerdotes separados.\nDD: ¡Interrumpir! Cortar Dark Mending de los sacerdotes."
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: ¡Protección contra el fuego! Ira de Ragnaros lanza lejos al cuerpo a cuerpo: luego volver.\nAll: Fase de los hijos (tras 3 min o cuando se sumerge): matar a todos los Hijos de la Llama.\nTank: Segundo tanque listo cuando el primero salga despedido.\nHealer: Repartidos, los de distancia no demasiado cerca (Lava Burst).\nDD: Cuerpo a cuerpo: controlar el maná; distancia: mantener la distancia."
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Flame Buffet se acumula: los de distancia tras los pilares para que se quite.\nTank: Dos tanques tras los pilares, Wing Buffet empuja hacia atrás.\nDD: Capa de escamas de Onyxia obligatoria."
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: Quitar Maldición de Gehennas (menos sanación) al instante.\nAll: Salir de la Lluvia de Fuego.\nTank: Tanquear a los dos Flamewakers por separado.\nDD: Flamewakers primero, luego Gehennas."
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: Quitar Maldición de Lucifron e Impending Doom al instante (magos/druidas, sacerdotes/paladines).\nTank: Tanquear a los dos guardias por separado: ¡control mental!\nHealer: Repartidos, disipar a los jugadores con control mental.\nDD: Primero los guardias, luego Lucifron."
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: Bomba viviente: ¡salir de la banda YA!\nAll: Inferno: lejos del jefe, disipar Ignite Mana.\nTank: Mantener el centro, salir un momento con Inferno.\nDD: Cuerpo a cuerpo, atrás con Inferno."
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: Ojo al reflejo de magia/escudo de daño de los guardias: entonces parar el daño.\nTank: Un guardia por tanque, los magos polimorfan a los guardias de élite.\nDD: Guardias sanadores (Flamewaker Healer) primero."
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: Nunca delante ni detrás de Onyxia (aliento y coletazo).\nAll: Fase 2 (65%): esquivar las bolas de fuego, no entrar en las cuevas.\nAll: Fase 3 (40%): miedo: Custodia de miedo/Tótem de tremor listos, evitar las grietas de lava.\nTank: Onyxia de lado contra la pared, cabeza lejos de la banda.\nTank: Fase 2: recoger las crías. Fase 3: recuperar el agro al instante.\nHealer: El tanque tiene prioridad, repartidos en fase 2.\nDD: Esperar 3 ataques del tanque. Fase 2: crías primero."
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: Pánico: Custodia de miedo/Tótem de tremor; cazadores: Disparo tranquilizante en Frenesí.\nAll: Salir del fuego de lava del suelo.\nTank: Magmadar de espaldas a la banda.\nDD: Los de distancia repartidos atrás."
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: Fase 1: dragonantes por ambos lados, ojo a las llamadas de clase.\nAll: Fase 3 (20%): los esqueletos se levantan de nuevo: matarlos otra vez.\nTank: Nefarian contra la pared, miedo: Custodia de miedo.\nHealer: Llamada de clase para sacerdotes: la sanación hace daño, cuidado.\nDD: Cazadores/guerreros: ojo a las llamadas de clase (sin armas, actitud)."
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: Fase 1: destruir los huevos (control mental con el orbe), recoger los adds.\nAll: Tras todos los huevos: jefe en la sala: Nova de Fuego.\nTank: Juntar los adds en las escaleras.\nDD: Magos y dragonantes primero."
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Frenesí: cazadores, Disparo tranquilizante.\nTank: Dos tanques, ojo a Wing Buffet.\nDD: Capa de escamas de Onyxia obligatoria."
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Sombra de Ebanorroca cura al jefe: el tanque con el perjuicio cambia.\nTank: Dos tanques cambian con Sombra.\nDD: Capa de escamas de Onyxia obligatoria."
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: Empuje: colocarse contra la pared.\nTank: Dos tanques, Knock Away reparte el agro.\nDD: Golpe mortal en el tanque: sanadores, atentos."
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: Se teletransporta: quien tenga el agro, que no huya.\nAll: Quitar Maldición de Shazzrah; Explosión Arcana: cuerpo a cuerpo a distancia.\nTank: Volver a él justo tras cada traslación.\nHealer: Disipar (Deaden Magic)."
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: Dos de los cinco tipos de aliento por semana: el aliento se evita tras la esquina.\nAll: Hourglass Sand para la aflicción de bronce.\nTank: Tanquear en la puerta, banda tras la esquina.\nDD: Disparo tranquilizante en Frenesí."
T["Alt halten: alle Werte und Bewertung. Shift: Blizzard-Vergleich."] = "Mantén Alt: todos los valores y la puntuación. Mayús: comparación de Blizzard."
T["Alt loslassen: kompakter Vergleich. Shift: Blizzard-Vergleich."] = "Suelta Alt: vista compacta. Mayús: comparación de Blizzard."
T["Altes Oasis"] = "Oasis antiguo"
