T["Banner auf der Uebersicht: Midas, das Auktionshaus-Addon von Rebo aus der Gilde OASIS"] = "Banner en el resumen: Midas, el addon de casa de subastas de Rebo, de la hermandad OASIS"
T["Befoerderung vorschlagen nach"] = "Sugerir ascenso tras"
T["Beim naechsten Wurf siehst du alt aus!"] = "¡En la próxima tirada estás acabado!"
