T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "El cliente no permite a Oasis activar el registro de combate: escribe /combatlog tú mismo."
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "El contenido de la sección elegida. El resumen muestra quién está conectado, qué hay pendiente y qué hay de nuevo."
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "El botón del minimapa o /oa abre Oasis. Con la raya de arriba a la derecha la ventana se vuelve una barra estrecha."
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "El canal de oficiales (/o) con historial: solo para rangos con permiso de chat de oficiales."
T["Der gelbe Strich links in der Liste zeigt das an."] = "Lo indica la raya amarilla a la izquierda de la lista."
T["Details schliessen"] = "Cerrar detalles"
T["Deutlicher Standard-Ton bei Online-Meldungen"] = "Sonido estándar más claro en avisos de conexión"
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "Las estadísticas de personaje no están disponibles en este cliente."
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "La dirección de la hermandad te ha bloqueado los efectos de sonido."
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "La barra está desde que entras y se queda: la X de la ventana solo cierra la ventana."
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "El porcentaje compara la puntuación del objeto para tu rol, no tu daño total. Los efectos son estimaciones."
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "La estadística no ofrece ahora un valor legible."
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "El centro de tu hermandad. En 30 segundos sabrás moverte: aquí va lo esencial."
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "Se bloqueó la función protegida. La causa exacta aún se desconoce."
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "Aún no se ha encontrado la estadística de personaje adecuada."
T["Die vollstaendigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."] = "Los textos completos de las licencias están en la carpeta de Oasis: CREDITS.txt, LICENSE y LICENSE-MIT.txt."
T["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "Estos rangos de hermandad (0 = maestro de hermandad) pueden votar en el consejo de botín."
