T["Nicht enthalten (oeffentliche Version): Meme-Sounds, Musik und Gilden-Emojis gibt es nur in der Gildenversion."] = "No incluido (versión pública): los sonidos meme, la música y los emojis de hermandad solo están en la versión de hermandad."
T["Nicht gefunden"] = "No encontrado"
T["Niemand ist fuer Soundeffekte gesperrt."] = "Nadie tiene bloqueados los efectos de sonido."
T["Niemand online"] = "Nadie conectado"
T["Noch eine Runde - ich will meine Ehre zurueck!"] = "Otra ronda: ¡quiero recuperar mi honor!"
T["Noch kein Crit erfasst. Kritische Treffer zaehlen automatisch, sobald du allein in der offenen Welt kaempfst."] = "Aún no hay críticos registrados. Los golpes críticos cuentan automáticamente mientras luchas en solitario en el mundo abierto."
T["Noch kein Termin geplant. Oben links: Was, Tag, Uhrzeit - dann 'Event anlegen'."] = "Aún no hay eventos previstos. Arriba a la izquierda: qué, día, hora; luego 'Crear evento'."
T["Noch kein lesbarer eigener Crit erfasst. Neue kritische Treffer werden automatisch aufgezeichnet."] = "Aún no hay un crítico tuyo legible. Los nuevos golpes críticos se registran automáticamente."
T["Noch kein positiver Einzelrekord gemeldet."] = "Aún no se ha comunicado ningún récord de golpe único positivo."
T["Noch keine Durchsagen. Schreib links die erste - Ueberschrift, Nachricht, senden."] = "Aún no hay avisos. Escribe el primero a la izquierda: título, mensaje, enviar."
T["Noch keiner bestaetigt - der Twink traegt dich mit /oa twink als Main ein."] = "Ninguno confirmado aún: el secundario te pone como principal con /oa twink."
T["Nur Helfer online"] = "Solo ayudantes conectados"
T["Nur aktuelles Gebiet"] = "Solo zona actual"
T["Nur falls WoW die Rang-Rechte nicht liefert: bis zu welchem Gildenrang andere als Offizier gelten (fuer die Pruefung empfangener Daten)."] = "Solo si WoW no ofrece los permisos de rango: hasta qué rango de hermandad cuentan los demás como oficiales (para comprobar los datos recibidos)."
T["Nur geoeffnete"] = "Solo abiertas"
T["Nur wenn er Oasis hat - sonst bleibt die Reaktion bei dir"] = "Solo si tiene Oasis; si no, la reacción se queda contigo"
T["OASIS Musik"] = "Música de OASIS"
T["Oasis-Nutzer dezent markieren"] = "Marcar discretamente a los usuarios de Oasis"
T["Oasis-Nutzer im Tooltip markieren"] = "Marcar a los usuarios de Oasis en el tooltip"
T["Oasis-Standard"] = "Estándar de Oasis"
T["Oasis: Alarm 2"] = "Oasis: Alarma 2"
T["Oasis: Fenster auf"] = "Oasis: Abrir ventana"
T["Oasis: Fenster zu"] = "Oasis: Cerrar ventana"
T["Oeffnet diesen Dungeon im Journal von FojjiCore: Karten, Routen, Drop-Chancen."] = "Abre esta mazmorra en el diario de FojjiCore: mapas, rutas, probabilidades de botín."
T["Offene Gruppensuchen der Gilde - Klick: Gruppen"] = "Búsquedas de grupo abiertas de la hermandad - clic: Grupos"
T["Offiziere bis Gildenrang (Ersatz)"] = "Oficiales hasta el rango de hermandad (reserva)"
T["Ohne Gruppe und ausserhalb von Dungeons zaehlt jeder kritische Treffer auf dein Ziel sofort fuer Hoechster Crit - ohne Logdatei."] = "Sin grupo y fuera de mazmorras, cada golpe crítico a tu objetivo cuenta al instante para Crítico más alto, sin archivo de registro."
T["Pause"] = "Pausa"
T["Plaetze"] = "Huecos"
T["Privat: Twink-Gespraeche unter dem Main"] = "Privado: conversaciones con secundarios bajo el principal"
T["Privat: wer online ist, gruen hinterlegen"] = "Privado: fondo verde para quien está conectado"
T["Protokoll & Export"] = "Registro y exportación"
T["Protokoll der Leitung, Auffaelligkeiten und Export der Gildendaten."] = "Registro de la dirección, anomalías y exportación de los datos de la hermandad."
T["Quelle: Blizzards Schadensanzeige."] = "Fuente: medidor de daño de Blizzard."
T["Quelle: Charakterstatistik. Crit-Status unbekannt."] = "Fuente: estadísticas del personaje. Estado de crítico desconocido."
T["Quelle: bestaetigte Crits aus Kampflog oder Logdatei."] = "Fuente: críticos confirmados del registro de combate en vivo o de archivo."
T["Quelle: eigene Crits beim Solo-Spiel. In Gruppe und Dungeon meldet WoW Addons nicht, wer getroffen hat."] = "Fuente: tus críticos jugando en solitario. En grupo y mazmorra WoW no dice a los addons quién dio el golpe."
T["Quelle: eigene Crits. Solo sicher erkannt; in Gruppe und Dungeon geschaetzt (Treffer direkt nach dem eigenen Angriff)."] = "Fuente: tus críticos. Fiable en solitario; estimado en grupo y mazmorra (golpe justo tras tu ataque)."
T["Quellen fuer Dungeons, Bosse, Beute und Quests"] = "Fuentes de mazmorras, jefes, botín y misiones"
T["Questbelohnung: beste Wahl markieren"] = "Recompensa de misión: marcar la mejor opción"
T["Quests & Karte"] = "Misiones y mapa"
T["Raid auswerten"] = "Analizar bandas"
T["Raid, Gildenabend oder Event eintragen, sichtbar fuer alle."] = "Añade una banda, noche de hermandad o evento, visible para todos."
T["Raid-Gruppen lassen sich im Kampf nicht umsortieren."] = "Los grupos de banda no se pueden reordenar en combate."
T["Raid: wer war dabei und wie gut ist die Ausruestung der Gilde."] = "Banda: quién asistió y qué nivel tiene el equipo de la hermandad."
T["Rang aendern, befoerdern, zurueckstufen und mehr"] = "Cambiar rango, ascender, degradar y más"
T["Rang-Wappen, Profilrahmen, Stufen-Abzeichen, Wappen, Ziffern, Deathroll-Grafiken, Logos, Effekte und Designs stammen vom Oasis-Autor. Die Dashboard-Banner hat der Autor mit KI erstellt."] = "Los blasones de rango, marcos de perfil, insignias de nivel, emblemas, cifras, gráficos de Deathroll, logos, efectos y diseños son del autor de Oasis. Los banners del panel los creó el autor con IA."
T["Reaktionen an den Gespraechspartner schicken"] = "Enviar reacciones a tu interlocutor"
T["Rechenzeit jetzt"] = "Tiempo de cálculo ahora"
T["Rechte vergeben"] = "Asignar permisos"
T["Respec ab 1 Punkt, stuendlich 1 guenstiger"] = "respec desde 1 punto, 1 más barato cada hora"
T["Revanche annehmen"] = "Aceptar revancha"
T["Revanche! Diesmal gewinne ich."] = "¡Revancha! Esta vez gano yo."
T["Rohwerte"] = "Valores en bruto"
T["Rollenwertung"] = "Puntuación de rol"
T["Rueckkehrer melden"] = "Avisar de regresos"
T["Schaltet beim Einloggen das Kampflog ein. Noetig fuer Hoechster Crit und Crit-Heilung: danach ImportCrits.bat im Oasis-Ordner und /reload."] = "Activa el registro de combate al iniciar sesión. Necesario para Crítico más alto y Sanación crítica: después ejecuta ImportCrits.bat en la carpeta de Oasis y haz /reload."
T["Schaut nur kurz raus"] = "Solo se asoma un momento"
T["Schon fertig? Ich will Revanche!"] = "¿Ya está? ¡Quiero la revancha!"
T["Schon so lange in der Gilde"] = "Ya lleva tanto en la hermandad"
T["Schrecken des Waldes von Elwynn"] = "Terror del Bosque de Elwynn"
T["Schreibe eine Durchsage: alle mit Oasis bekommen einen Hinweis mit Ton."] = "Escribe un aviso: todos los que tienen Oasis reciben una notificación con sonido."
T["Schrott verkaufen: Oasis wollte Taschen-Items einzeln verkaufen (ab 0.5.478 ueber Blizzards Schrott-Verkauf)."] = "Vender chatarra: Oasis intentó vender objetos de la bolsa uno a uno (desde 0.5.478 con la venta de chatarra de Blizzard)."
