T["Setzt die Zeile, in die du tippst, ueber den Chat statt darunter - praktisch, wenn der Chat unten am Bildschirmrand klebt und die Eingabe sonst abgeschnitten wird."] = "Coloca la línea en la que escribes encima del chat en vez de debajo: útil si el chat está pegado al borde inferior de la pantalla y la entrada quedaría cortada."
