T["So geht es: /combatlog an, kaempfen, dann ImportCrits.bat im Oasis-Ordner doppelklicken und /reload."] = "Cómo: activa /combatlog, lucha, luego haz doble clic en ImportCrits.bat en la carpeta de Oasis y /reload."
T["So kommt dein Crit in die Rangliste"] = "Así llega tu crítico a la clasificación"
T["So lange hat jeder Zeit zu waehlen. Wer nichts waehlt, passt."] = "Este es el tiempo que tiene cada uno para elegir. Quien no elige, pasa."
T["So viel Prozent vom Topf gehen vor dem Aufteilen an die Gildenbank."] = "Este porcentaje del bote va al banco de hermandad antes del reparto."
T["So wie du gerade aussiehst"] = "Tal como te ves ahora mismo"
