T["Spieler duerfen einen Einsatz (z.B. Gold) angeben. Aus: alle Spiele laufen ohne Einsatz. Bitte die Regeln eures Realms zu Gluecksspiel beachten."] = "Los jugadores pueden indicar una apuesta (p. ej. oro). Desactivado: todas las partidas son sin apuesta. Respeta las normas de tu reino sobre juegos de azar."
