T["Statistiken erneut pruefen"] = "Volver a comprobar estadísticas"
T["Stumm: Neuigkeiten dieses Reiters erscheinen nicht am Minimap-Knopf und in der Topbar"] = "Silenciado: las novedades de esta pestaña no aparecen en el botón del minimapa ni en la barra superior"
T["Sucht immer noch seine Frau"] = "Sigue buscando a su esposa"
T["Symbole und Abzeichen-Symbole von Lorc und Delapouite - CC BY 3.0"] = "Iconos e iconos de insignias de Lorc y Delapouite – CC BY 3.0"
