T["Twinks ausblenden"] = "Ocultar secundarios"
T["Twinks ausserhalb der Gilde: unter Datenschutz"] = "Secundarios fuera de la hermandad: en Privacidad"
T["Uebernimmt, was du in FojjiCores Wunschliste markiert hast. Die Gilde sieht diese Wuensche dann hier."] = "Copia lo que marcaste en la lista de deseos de FojjiCore. La hermandad verá esos deseos aquí."
T["Um so viel Gold muss jedes neue Gebot hoeher sein."] = "Cada nueva puja debe ser este oro más alta."
T["Ungueltiger Crit-Importcode."] = "Código de importación de críticos no válido."
T["Upgrade fuer"] = "Mejora para"
T["Verbesserung"] = "Mejora"
T["Verknuepft: %s"] = "Vinculado: %s"
T["Viel Spass mit Oasis!"] = "¡Que disfrutes de Oasis!"
T["Voice: %s"] = "Voz: %s"
T["Voriger Boss"] = "Jefe anterior"
T["Vorlage waehlen"] = "Elegir plantilla"
T["Vorschlaege, wer einen hoeheren Rang verdient hat."] = "Sugerencias de quién se ha ganado un rango superior."
T["Wache von Orgrimmar"] = "Guardia de Orgrimmar"
T["Waehle unten, was du tun moechtest - Oasis bringt dich an die richtige Stelle."] = "Elige abajo lo que quieres hacer: Oasis te lleva al lugar correcto."
T["Wartet auf einen Kuss"] = "Espera un beso"
T["Was die Leitung geaendert hat, Auffaelligkeiten, Daten sichern."] = "Qué cambió la dirección, anomalías, copia de seguridad de datos."
T["Was du fuer den naechsten Raid noch brauchst - Widerstaende, Verbrauchsgueter, Haltbarkeit, Schluessel"] = "Lo que aún necesitas para la próxima banda: resistencias, consumibles, durabilidad, llaves"
T["Was liegt wo? Suche ueber alle deine Charaktere, ihre Bank und die Gildenbank"] = "¿Qué hay dónde? Busca en todos tus personajes, su banco y el banco de hermandad"
T["Was moechtest du tun?"] = "¿Qué quieres hacer?"
T["Was?"] = "¿Qué?"
T["Weitere Gildenevents folgen hier."] = "Aquí vendrán más eventos de hermandad."
T["Weitere Plaetze fuellen sich, sobald mehr Gildenmitglieder mit Oasis gekaempft haben."] = "Se llenarán más puestos cuando más miembros con Oasis hayan combatido."
T["Weitere Upgrades in diesem Dungeon"] = "Más mejoras en esta mazmorra"
T["Welche Seiten sieht die Gilde - und ab welchem Rang."] = "Qué páginas ve la hermandad y desde qué rango."
T["Welcher Rang darf Durchsagen, Termine, Bank und mehr."] = "Qué rango puede usar avisos, eventos, banco y más."
T["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "Quien ya recibió un objeto por necesidad esa noche pasa, en necesidad, detrás de todos los que no tienen objeto (mismo rango de tirada)."
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "Quien reservó un objeto para el evento va antes que todos en necesidad."
T["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "Quién tiene qué beneficios en el grupo o la banda, y quién puede dar lo que falta"
T["Wer ist in der Gilde, welcher Rang, wer hat altes Oasis."] = "Quién está en la hermandad, qué rango, quién tiene un Oasis antiguo."
T["Wer war lange nicht online - aufraeumen mit einem Klick."] = "Quién lleva mucho sin conectarse: limpia con un clic."
T["Wie die Schrift"] = "Igual que el texto"
T["Wieder am Talentfenster andocken"] = "Acoplar de nuevo a la ventana de talentos"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "En grupo, WoW no dice a los addons quién dio un golpe. Oasis solo cuenta un golpe crítico si sigue directamente a tu ataque y coincide con el medidor de daño tras el combate. En la clasificación aparece como estimado."
T["WoW-Klassiker"] = "Clásicos de WoW"
T["Wochenaufgaben %d/%d"] = "Tareas semanales %d/%d"
T["World of Warcraft und zugehoerige Namen, Wappen und Grafiken sind Marken von Blizzard Entertainment. Oasis ist ein Fan-Projekt und steht in keiner Verbindung zu Blizzard."] = "World of Warcraft y los nombres, blasones y gráficos asociados son marcas de Blizzard Entertainment. Oasis es un proyecto de fans y no está afiliado a Blizzard."
T["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "Tiradas: orden necesidad > segunda especialización > transfiguración, luego la tirada. Puntos: decide la prioridad según los puntos de botín. Consejo de botín: los oficiales votan, el maestro despojador adjudica."
T["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "Engranaje = ajustes (aspecto, sonidos, avisos). Al lado, el idioma y, para la dirección de la hermandad, la corona."
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "Muestra qué materiales pueden dar al desencantar los objetos verdes, azules y épicos"
T["Zeigt in der Suche an, dass ihr per Sprache redet (Discord o.ae.). Beitreten regelt weiter Blizzard bzw. dein Gruppenleiter."] = "Muestra en el listado que se habla por voz (Discord, etc.). De unirse se siguen encargando Blizzard o tu líder de grupo."
T["Zeigt nur Mains. Twinks sind Charaktere, die einem anderen Main zugeordnet sind."] = "Muestra solo principales. Los secundarios son personajes asignados a otro principal."
T["Zeigt nur die Kopfzeile mit der Anzahl der Builds."] = "Muestra solo la cabecera con el número de builds."
T["Zeigt sofort, wer aus der Gilde dieselben Quests hat und gerade online ist - ein Klick laedt ihn ein."] = "Muestra al instante quién de la hermandad tiene las mismas misiones y está conectado: un clic lo invita."
T["Zielt jemand einen Boss an, zu dem es eine Taktik gibt, erscheint ein kurzer Hinweis (ausserhalb des Kampfes)."] = "Si alguien selecciona a un jefe que tiene táctica, aparece un aviso breve (fuera de combate)."
T["Zu leicht. Traust du dich nochmal?"] = "Demasiado fácil. ¿Te atreves otra vez?"
T["Zufaelliger Gruss, wenn jemand online kommt"] = "Saludo aleatorio cuando alguien se conecta"
T["Zweiklang statt kurzem Ton, wenn die Person keinen eigenen Online-Sound gewaehlt hat"] = "Dos tonos en vez de un tono corto si la persona no ha elegido un sonido de conexión"
